import Quartz
import Foundation

// This script will send keyboard and mouse events to automate the UI

// First, dismiss the dialog with Escape key
func sendEscapeKey() {
    let keyCode: CGKeyCode = 53 // Escape key
    let source = CGEventSource(stateID: .combinedSessionState)

    let keyDown = CGEvent(keyboardEventSource: source, virtualKey: keyCode, keyDown: true)!
    let keyUp = CGEvent(keyboardEventSource: source, virtualKey: keyCode, keyDown: false)!

    keyDown.post(tap: .cghidEventTap)
    keyUp.post(tap: .cghidEventTap)

    print("Sent Escape key")
}

// Send a mouse click to dismiss the dialog
func clickCancel() {
    // Cancel button is at approximately (238, 862) based on the screenshot
    let point = CGPoint(x: 238, y: 862)

    let mouseDown = CGEvent(mouseEventSource: nil, mouseType: .leftMouseDown, mouseCursorPosition: point, timestamp: 0)!
    let mouseUp = CGEvent(mouseEventSource: nil, mouseType: .leftMouseUp, mouseCursorPosition: point, timestamp: 0)!

    mouseDown.post(tap: .cghidEventTap)
    mouseUp.post(tap: .cghidEventTap)

    print("Clicked Cancel button")
}

// Click on Project Phoenix room
func clickProjectPhoenix() {
    let point = CGPoint(x: 250, y: 573) // Project Phoenix location

    let mouseDown = CGEvent(mouseEventSource: nil, mouseType: .leftMouseDown, mouseCursorPosition: point, timestamp: 0)!
    let mouseUp = CGEvent(mouseEventSource: nil, mouseType: .leftMouseUp, mouseCursorPosition: point, timestamp: 0)!

    mouseDown.post(tap: .cghidEventTap)
    mouseUp.post(tap: .cghidEventTap)

    print("Clicked Project Phoenix")
    sleep(1)
}

